from PIL import Image
import chess

# Load image
img = Image.open('/app/chess_board.png')
pixels = img.load()
square_size = 80

# Let's try a different approach: look at the actual piece images more carefully
# by examining sub-regions and comparing shapes

def extract_piece_region(file, rank, img, square_size):
    """Extract the actual piece region from the board"""
    x_start = file * square_size
    y_start = (7 - rank) * square_size
    x_end = x_start + square_size
    y_end = y_start + square_size

    # Crop the square
    return img.crop((x_start, y_start, x_end, y_end))

# Let's manually examine specific piece positions
# and look for distinguishing features

def count_dark_pixels_by_region(file, rank, pixels, square_size):
    """Count dark pixels in top, middle, bottom regions"""
    x_center = file * square_size + square_size // 2
    y_start = (7 - rank) * square_size
    y_center = y_start + square_size // 2

    regions = {
        'top': 0,
        'middle': 0,
        'bottom': 0
    }

    # Top region (rank height/4)
    for x in range(x_center - 20, x_center + 21):
        for y in range(y_start + 10, y_start + 20):
            if 0 <= x < 640 and 0 <= y < 640:
                r, g, b = pixels[x, y]
                if (r + g + b) / 3 < 150:
                    regions['top'] += 1

    # Middle region
    for x in range(x_center - 20, x_center + 21):
        for y in range(y_center - 10, y_center + 11):
            if 0 <= x < 640 and 0 <= y < 640:
                r, g, b = pixels[x, y]
                if (r + g + b) / 3 < 150:
                    regions['middle'] += 1

    # Bottom region
    for x in range(x_center - 20, x_center + 21):
        for y in range(y_start + 60, y_start + 70):
            if 0 <= x < 640 and 0 <= y < 640:
                r, g, b = pixels[x, y]
                if (r + g + b) / 3 < 150:
                    regions['bottom'] += 1

    return regions

# Analyze all pieces
print("Regional dark pixel distribution:")
pieces_info = [
    (0, 5, "a6"), (0, 7, "a8"), (1, 6, "b7"), (2, 5, "c6"), (2, 7, "c8"),
    (3, 4, "d5"), (4, 5, "e6"), (5, 4, "f5"), (5, 6, "f7"), (5, 7, "f8"), (6, 6, "g7")
]

for file, rank, sq_name in pieces_info:
    regions = count_dark_pixels_by_region(file, rank, pixels, square_size)
    print(f"{sq_name}: top={regions['top']:3d} mid={regions['middle']:3d} bot={regions['bottom']:3d}")

